<script setup>
import {ref,watch,computed,onUnmounted} from 'vue';
import {api,scope,state,company,useResource,can,allowedApi,ask,notify,changed} from '../lib/workspace';
import {date as displayDate} from '../lib/format';
import Icon from '../components/Icon.vue';import BaseModal from '../components/BaseModal.vue';import DateInput from '../components/DateInput.vue';import CfopInput from '../components/CfopInput.vue';
const tab=ref('table'),query=ref(''),direction=ref(''),asOf=ref(state.period+'-01'),page=ref(1),busy=ref(false),error=ref(''),detail=ref(null),mapping=ref(null),catalog=ref(null);let baseline='';
const {data,loading,error:loadError,reload}=useResource(()=>api(scope('/cfop-reference?'+new URLSearchParams({search:query.value,direction:direction.value,date:asOf.value,page:String(page.value)}))),{rows:[],total:0});
const {data:mappings,reload:reloadMappings}=useResource(()=>allowedApi('fiscal.parameters',scope('/fiscal-import-mappings')));
watch([query,direction,asOf],()=>{page.value=1;reload()});watch(page,reload);
const totalPages=computed(()=>Math.max(1,Math.ceil(data.value.total/50)));
onUnmounted(()=>{if(mapping.value||catalog.value)state.editor=null});
function editMapping(row=null){mapping.value=row?{...row.data,id:row.id,version:row.version,active:row.active}:{direction:'incoming',model:'55',source_cfop:'',target_cfop:'',valid_from:asOf.value,valid_to:'',reason:'',responsible:state.session.user.username,active:true};baseline=JSON.stringify(mapping.value);error.value='';state.editor={name:'Associação de CFOP',companyId:state.companyId};}
function editCatalog(row){const c=row.company_catalog;catalog.value=c?{...c}:{kind:'cfop',code:row.code,description:row.title,direction:row.direction,valid_from:row.wording_valid_from,valid_to:row.wording_valid_to,source:data.value.source+' · '+data.value.edition,active:true};catalog.value.active=!!catalog.value.active;baseline=JSON.stringify(catalog.value);error.value='';state.editor={name:'CFOP da empresa',companyId:state.companyId};}
async function close(){if(busy.value)return;const value=mapping.value||catalog.value;if(value&&JSON.stringify(value)!==baseline&&!await ask({title:'Descartar alterações?',message:'O cadastro ainda não foi salvo.',confirmLabel:'Descartar',danger:true}))return;mapping.value=null;catalog.value=null;state.editor=null;}
async function saveMapping(){busy.value=true;error.value='';try{const m=mapping.value;await api(scope('/fiscal-import-mappings'+(m.id?'/'+m.id:'')),{method:m.id?'PUT':'POST',body:m});mapping.value=null;state.editor=null;await reloadMappings();changed();notify('Associação salva somente nesta empresa.');}catch(e){error.value=e.message}finally{busy.value=false}}
async function saveCatalog(){busy.value=true;error.value='';try{const c=catalog.value;await api(scope('/catalogs'+(c.id?'/'+c.id:'')),{method:c.id?'PUT':'POST',body:c});catalog.value=null;state.editor=null;await reload();changed();notify('Cadastro CFOP atualizado nesta empresa.');}catch(e){error.value=e.message}finally{busy.value=false}}
async function copyTable(){const reason=await ask({title:'Cadastrar a referência na empresa?',message:`Copiar os códigos da referência para ${company.value.name} na data ${displayDate(asOf.value)}. Cadastros existentes serão preservados.`,inputLabel:'Motivo',required:true,confirmLabel:'Cadastrar tabela'});if(!reason)return;busy.value=true;try{const r=await api(scope('/cfop-reference/apply'),{method:'POST',body:{edition:data.value.edition,date:asOf.value,reason}});notify(`${r.created} CFOPs cadastrados; ${r.preserved} existentes preservados.`);changed();await reload();}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">ESCRITURAÇÃO FISCAL</div><h1>CFOP e associações</h1><p>{{company?.name}} · referência oficial e escolhas da empresa para importar.</p></div><button v-if="tab==='table'&&can('fiscal.masters','create')" class="button primary" :disabled="busy||!data.edition" @click="copyTable"><Icon name="import"/>Cadastrar tabela na empresa</button><button v-if="tab==='mappings'&&can('fiscal.parameters','create')" class="button primary" @click="editMapping()"><Icon name="plus"/>Nova associação</button></header>
<div class="modal-tabs"><button :class="{selected:tab==='table'}" @click="tab='table'">Tabela CFOP</button><button v-if="can('fiscal.parameters')" :class="{selected:tab==='mappings'}" @click="tab='mappings'">Associações de importação</button></div><p v-if="error||loadError" class="message error" role="alert">{{error||loadError}}</p>
<template v-if="tab==='table'"><section class="panel"><div class="table-toolbar"><div class="search-field"><Icon name="search"/><input v-model="query" aria-label="Pesquisar CFOP" placeholder="Código, descrição ou nota explicativa"/></div><select v-model="direction" aria-label="Sentido do CFOP"><option value="">Entradas e saídas</option><option value="incoming">Entradas</option><option value="outgoing">Saídas</option></select><label>Data de referência<DateInput v-model="asOf" required/></label></div><div class="table-scroll"><table><thead><tr><th>CFOP</th><th>Descrição oficial</th><th>Redação</th><th>Na empresa</th><th>Ações</th></tr></thead><tbody><tr v-for="r in data.rows" :key="r.code"><td class="mono">{{r.code}}</td><td>{{r.title}}</td><td class="nowrap">{{displayDate(r.wording_valid_from)}}{{r.wording_valid_to?' a '+displayDate(r.wording_valid_to):''}}</td><td>{{r.company_catalog?'Cadastrado':'Referência disponível'}}</td><td><div class="actions"><button class="text-button" @click="detail=r">Nota explicativa</button><button v-if="can('fiscal.masters',r.company_catalog?'edit':'create')" class="button small" @click="editCatalog(r)">{{r.company_catalog?'Editar na empresa':'Cadastrar'}}</button></div></td></tr></tbody></table></div><footer class="table-footer"><span>{{data.total}} códigos · página {{page}} de {{totalPages}}</span><div class="actions"><button class="button small" :disabled="page===1||loading" @click="page--">Anterior</button><button class="button small" :disabled="page>=totalPages||loading" @click="page++">Próxima</button></div></footer></section><details class="panel panel-body"><summary>Origem e cobertura da referência</summary><p>{{data.scope}}</p><p><a :href="data.source" target="_blank" rel="noopener">Consultar CONFAZ</a> · {{data.edition}} · consulta em {{displayDate(data.retrieved_on)}}</p><p>A tabela identifica operações. A escolha de CFOP não concede crédito nem define alíquota automaticamente.</p></details></template>
<section v-else class="panel"><div class="panel-body"><p>Associe o CFOP original à operação desta empresa. Na importação, a associação só vale para o sentido, modelo e datas cadastrados. O código original permanece preservado.</p></div><div class="table-scroll"><table><thead><tr><th>Sentido / modelo</th><th>Origem → escrituração</th><th>Vigência</th><th>Responsável</th><th>Situação</th><th></th></tr></thead><tbody><tr v-for="m in mappings" :key="m.id"><td>{{m.data.direction==='incoming'?'Entrada':'Saída'}} · {{m.data.model||'Todos'}}</td><td class="mono">{{m.data.source_cfop}} → {{m.data.target_cfop}}</td><td>{{displayDate(m.data.valid_from)}}{{m.data.valid_to?' a '+displayDate(m.data.valid_to):''}}</td><td>{{m.data.responsible}}</td><td>{{m.active?'Ativa':'Inativa'}} · v{{m.version}}</td><td><button v-if="can('fiscal.parameters','edit')" class="button small" @click="editMapping(m)">Editar associação</button></td></tr><tr v-if="!mappings.length"><td colspan="6">Nenhuma associação cadastrada. A importação solicitará os CFOPs de escrituração que faltarem.</td></tr></tbody></table></div></section>
<BaseModal v-if="detail" :title="`CFOP ${detail.code}`" @close="detail=null"><h3>{{detail.title}}</h3><p style="white-space:pre-line">{{detail.note}}</p><p>{{detail.legal_source}}</p><template #footer><button class="button" @click="detail=null">Fechar</button></template></BaseModal>
<BaseModal v-if="mapping" :title="mapping.id?'Editar associação':'Nova associação de CFOP'" :subtitle="company?.name" @close="close"><p v-if="error" class="message error" role="alert">{{error}}</p><form id="cfop-mapping-form" @submit.prevent="saveMapping"><div class="form-grid"><label>Operação<select v-model="mapping.direction"><option value="incoming">Entrada</option><option value="outgoing">Saída</option></select></label><label>Modelo<select v-model="mapping.model"><option value="">Todos</option><option value="55">55 · NF-e</option><option value="65">65 · NFC-e</option><option value="57">57 · CT-e</option></select></label><label>CFOP da origem *<CfopInput v-model="mapping.source_cfop" :date="mapping.valid_from" required/></label><label>CFOP de escrituração *<CfopInput v-model="mapping.target_cfop" :direction="mapping.direction" :date="mapping.valid_from" required/></label><label>Início da vigência *<DateInput v-model="mapping.valid_from" required/></label><label>Fim da vigência<DateInput v-model="mapping.valid_to"/></label><label class="span-2">Fundamento da associação *<textarea v-model="mapping.reason" required rows="2"/></label><label>Responsável *<input v-model="mapping.responsible" required/></label><label class="inline-choice"><input v-model="mapping.active" type="checkbox"/>Associação ativa</label></div></form><template #footer><button class="button" :disabled="busy" @click="close">Cancelar</button><button class="button primary" form="cfop-mapping-form" :disabled="busy">Salvar associação</button></template></BaseModal>
<BaseModal v-if="catalog" title="CFOP da empresa" :subtitle="company?.name" @close="close"><p v-if="error" class="message error" role="alert">{{error}}</p><form id="company-cfop-form" @submit.prevent="saveCatalog"><div class="form-grid"><label>CFOP<input :value="catalog.code" readonly/></label><label>Operação<select v-model="catalog.direction"><option value="incoming">Entrada</option><option value="outgoing">Saída</option></select></label><label class="span-2">Descrição na empresa *<textarea v-model="catalog.description" required rows="3"/></label><label>Início da vigência<DateInput v-model="catalog.valid_from"/></label><label>Fim da vigência<DateInput v-model="catalog.valid_to"/></label><label class="span-2">Fonte *<input v-model="catalog.source" required/></label><label class="inline-choice"><input v-model="catalog.active" type="checkbox"/>Cadastro ativo</label></div></form><template #footer><button class="button" :disabled="busy" @click="close">Cancelar</button><button class="button primary" form="company-cfop-form" :disabled="busy">Salvar CFOP</button></template></BaseModal>
</div></template>
